from datetime import datetime, time
from typing import Dict, Set


class Notifier:
    CHANNELS = ("email", "sms", "push")

    def __init__(self, quiet_start: time = time(22, 0), quiet_end: time = time(7, 0)) -> None:
        self.quiet_start = quiet_start
        self.quiet_end = quiet_end
        # Map user to their set of enabled channels
        self._user_channels: Dict[str, Set[str]] = {}

    def add_user(self, user: str) -> None:
        """Register a user with all channels enabled by default."""
        if user not in self._user_channels:
            self._user_channels[user] = set(self.CHANNELS)

    def set_channel(self, user: str, channel: str, enabled: bool) -> None:
        """Enable or disable a specific channel for a user."""
        if channel not in self.CHANNELS:
            raise ValueError(f"Unknown channel: {channel}. Expected one of {self.CHANNELS}")

        if user not in self._user_channels:
            self.add_user(user)

        if enabled:
            self._user_channels[user].add(channel)
        else:
            self._user_channels[user].discard(channel)

    def _is_quiet_hour(self, t: time) -> bool:
        """Check if a given time falls within the quiet hours."""
        if self.quiet_start <= self.quiet_end:
            # Quiet hours within the same calendar day (e.g., 01:00 to 05:00)
            return self.quiet_start <= t < self.quiet_end
        else:
            # Quiet hours span across midnight (e.g., 22:00 to 07:00)
            return t >= self.quiet_start or t < self.quiet_end

    def send(self, user: str, message: str, at: datetime) -> list[str]:
        """Send a message; returns the channels it was delivered to, in CHANNELS order."""
        if user not in self._user_channels:
            self.add_user(user)

        enabled_channels = self._user_channels[user]
        is_quiet = self._is_quiet_hour(at.time())

        delivered: list[str] = []
        for channel in self.CHANNELS:
            if channel not in enabled_channels:
                continue

            # During quiet hours, only 'email' is delivered; 'sms' and 'push' are muted
            if is_quiet and channel in ("sms", "push"):
                continue

            delivered.append(channel)

        return delivered
